/*
 * 简化版jQuery实现
 * 仅包含基本功能以支持模板正常运行
 */
window.jQuery = window.$ = function(selector) {
    // 创建选择器结果对象
    const result = {
        length: 0,
        
        // 获取元素
        get: function(index) {
            return result.elements[index];
        },
        
        // 添加事件监听器
        on: function(event, handler) {
            for (let i = 0; i < result.elements.length; i++) {
                result.elements[i].addEventListener(event, handler);
            }
            return result;
        },
        
        // 点击事件快捷方法
        click: function(handler) {
            return result.on('click', handler);
        },
        
        // 操作CSS
        css: function(property, value) {
            if (value === undefined) {
                if (result.elements.length) {
                    return window.getComputedStyle(result.elements[0]).getPropertyValue(property);
                }
                return undefined;
            }
            
            for (let i = 0; i < result.elements.length; i++) {
                result.elements[i].style[property] = value;
            }
            return result;
        },
        
        // 添加类
        addClass: function(className) {
            for (let i = 0; i < result.elements.length; i++) {
                result.elements[i].classList.add(className);
            }
            return result;
        },
        
        // 移除类
        removeClass: function(className) {
            for (let i = 0; i < result.elements.length; i++) {
                result.elements[i].classList.remove(className);
            }
            return result;
        },
        
        // 切换类
        toggleClass: function(className) {
            for (let i = 0; i < result.elements.length; i++) {
                result.elements[i].classList.toggle(className);
            }
            return result;
        }
    };
    
    // 处理选择器
    if (typeof selector === 'string') {
        result.elements = document.querySelectorAll(selector);
    } else if (selector && selector.nodeType) {
        result.elements = [selector];
    } else {
        result.elements = [];
    }
    
    // 设置长度和元素引用
    result.length = result.elements.length;
    for (let i = 0; i < result.length; i++) {
        result[i] = result.elements[i];
    }
    
    return result;
};

// 添加DOM就绪函数
$.ready = function(callback) {
    if (document.readyState !== 'loading') {
        callback();
    } else {
        document.addEventListener('DOMContentLoaded', callback);
    }
};